  function officeTransfer(m) {
    m.add("inner-office", "transfer", "Возвращаемся к ожидавшему офисному пакету", "Внутренний адрес назначения — офисный сервер, не VPN-шлюз.", ["Система выбрала wg0 для 172.19.115.180. У исходящего пакета адрес источника 10.7.0.2 — адрес ноутбука внутри VPN. WireGuard находит офисный peer по AllowedIPs.", "Здесь выделен один IP-пакет из подготовленного запроса к офисному сервису. TCP, TLS и HTTP повторно не разворачиваем: это отдельные обмены, а не обещание получить страницу ровно за два IP-пакета.", "В этот момент ноутбук ещё видит исходный IP-пакет. Сейчас WireGuard защитит его целиком: и внутренние адреса, и вложенные данные. Открытый ключ peer не используют как отдельный способ шифрования каждого пакета: данные защищают согласованные ключи передачи."], "Внутренний пакет подготовлен для офисного peer.", "Исходный пакет доступен на ноутбуке, но не наблюдателю в интернете.", null, null, "local", "Внутренний IP", innerFields(OFFICE, false), ["wg-routing", "wg-protocol"], { observer: "На этом локальном шаге новый пакет в интернет ещё не ушёл." }, [innerPacket(OFFICE, false)]);
    m.add("outer-office", "transfer", "Отправляем защищённую оболочку через интернет", "У одного обмена теперь два набора IP-адресов.", ["WireGuard помещает зашифрованный внутренний пакет в своё data message и передаёт его внутри UDP. Для внешней доставки используются физическая сеть ноутбука и домашний маршрутизатор.", "После домашнего NAT снаружи виден пакет 198.51.100.10 → 203.0.113.5, UDP 40000 → 51820. Адреса 10.7.0.2 → 172.19.115.180 остались внутри зашифрованной части. Домашний NAT меняет внешние адреса и порт, а не содержимое внутреннего IP-пакета."], "VPN-шлюз получил первый защищённый data message клиента.", "Снаружи видны оболочка, размеры и время; внутренние адреса и данные не читаются.", "client", "vpn", "vpn", "Зашифрованный IP", outerFields("Зашифрованный IP-пакет", false), ["wg-routing", "wg-protocol", "nat"], { observer: "198.51.100.10 → 203.0.113.5, UDP 40000 → 51820; внутренний IP скрыт." }, [outerPacket("Зашифрованный IP-пакет", false)]);
    m.add("gateway-decrypt", "transfer", "Шлюз проверяет и открывает внутренний пакет", "Защита туннеля заканчивается на VPN-шлюзе.", ["Шлюз проверяет подлинность защищённого сообщения и расшифровывает его. Затем WireGuard проверяет внутренний адрес источника: этому клиентскому ключу разрешён 10.7.0.2/32.", "Теперь шлюз снова видит исходный пакет 10.7.0.2 → 172.19.115.180. Он выбирает дальнейший маршрут в офисную сеть. Если приложение не использует собственное шифрование, один VPN не защищает этот следующий участок."], "Пакет принят от настроенного peer; новый ключ клиента подтверждён.", "Внутренний IP открыт шлюзу, но не домашнему маршрутизатору.", null, null, "local", "Проверка + расшифрование", innerFields(OFFICE, false), ["wg-routing", "wg-protocol"], { observer: "Наблюдатель домашнего интернет-участка всё ещё имеет только внешнюю оболочку." }, [innerPacket(OFFICE, false)]);
    m.add("office-delivery", "transfer", "Доставляем пакет офисному серверу", "Шлюз пересылает пакет, а не превращается в нужное приложение.", ["В условиях опыта пересылка и правила доступа на шлюзе настроены. Офисный сервер получает пакет от 10.7.0.2. Внутренний SNAT здесь не используется: источник сохраняется.", "Сервер знает обратный маршрут к сети 10.7.0.0/24 через VPN-шлюз. Без обратного пути один успешный пакет к серверу не дал бы полноценного обмена."], "Офисный сервер получил пакет клиента.", "На офисном участке видны внутренние IP-адреса. Защита TCP-приложения зависит от его протокола.", "vpn", "server", "ip", "Внутренний IP", innerFields(OFFICE, false), ["linux-route", "wg-routing"], {}, [innerPacket(OFFICE, false)]);
    m.add("office-response", "transfer", "Сервер отвечает через офисный шлюз", "Направление внутренних адресов меняется на обратное.", ["Ответ адресован 10.7.0.2 и по офисному маршруту приходит к VPN-шлюзу. На шлюзе этот адрес связан с клиентским peer.", "Это обратный путь внутреннего пакета. До домашнего внешнего адреса 198.51.100.10 серверу здесь дела нет: его добавит внешняя доставка туннеля."], "У VPN-шлюза есть внутренний ответ для ноутбука.", "Офисный сервер видит адрес клиента внутри VPN, а не домашний внешний адрес.", "server", "vpn", "ip", "Ответ офиса", innerFields(OFFICE, true), ["wg-routing", "linux-route"], {}, [innerPacket(OFFICE, true)]);
    m.add("tunnel-response", "transfer", "Возвращаем ответ внутри WireGuard", "Домашний NAT доставляет внешний UDP-пакет ноутбуку.", ["Шлюз шифрует внутренний ответ 172.19.115.180 → 10.7.0.2. В интернете идёт другой пакет: 203.0.113.5 → 198.51.100.10, UDP 51820 → 40000.", "Домашняя запись NAT ещё действует и направляет его к 192.0.2.10:51821. Ноутбук проверяет сообщение и получает внутренний ответ. На клиенте источник 172.19.115.180 входит в AllowedIPs офисного peer."], "Ответ офисной страницы дошёл до ноутбука.", "Открытый внутренний пакет появляется у клиента после успешной проверки, не в домашнем маршрутизаторе.", "vpn", "client", "vpn", "Защищённый ответ", outerFields("Зашифрованный IP-пакет", true), ["wg-routing", "nat"], { result: "Офис доступен", observer: "Внешний обратный UDP-обмен; содержимое офисного ответа скрыто." }, [outerPacket("Зашифрованный IP-пакет", true), innerPacket(OFFICE, true)]);
  }
  var split = makeScenario("split");
  setup(split, false); officeTransfer(split);
  split.add("public-direct-route", "result", "Теперь открываем обычный публичный сайт", "Split tunnel означает разделение путей, а не отсутствие VPN.", ["Пусть обычный сайт находится по адресу 203.0.113.80. Он не входит в офисную сеть 172.19.0.0/16. Поэтому выбранный маршрут ведёт через домашний шлюз, не через wg0.", "Такой режим называют split tunnel (разделённый туннель): только выбранные направления идут в VPN. Офисная страница продолжает использовать VPN, а этот публичный сайт — нет."], "Для публичного сайта выбран обычный домашний выход.", "Публичный адрес сайта не скрыт от домашней сети из-за работающего офисного VPN.", null, null, "local", "Другой маршрут", localFields("Назначение " + WEB, "Домашний шлюз", "Офисный маршрут на этот адрес не распространяется."), ["linux-route", "wg-quick"], {}, [note("Не путать с HTTPS", "Если публичный сайт использует HTTPS, его содержимое защищает TLS. Это самостоятельная защита; она не делает передачу частью офисного VPN.")]);
  split.add("public-direct", "result", "Публичный сайт видит домашний внешний адрес", "В этой передаче нет оболочки WireGuard.", ["Домашний NAT заменяет источник обычного пакета на 198.51.100.10. Публичный сайт отвечает этому адресу, а NAT доставляет ответ ноутбуку по своей отдельной записи.", "VPN-шлюз в этом обмене не участвует. Две открытые страницы на одном ноутбуке могут иметь разные сетевые пути — это следствие выбранных маршрутов, а не вида окна браузера."], "Офис доступен через VPN; публичный сайт — напрямую.", "Сайт видит 198.51.100.10. Для наблюдателя видны адреса публичного обмена, но не обязательно содержимое HTTPS.", "home", "public", "ip", "Без WireGuard", [field("IPv4", "Прямой публичный выход", [["Источник → назначение", HOME + " → " + WEB, "После домашнего NAT."], ["WireGuard", "Не используется", "Этот пакет не попадал в wg0."]])], ["linux-route", "nat"], { result: "Два пути проверены", observer: "Публичный сайт 203.0.113.80 виден в обычном внешнем IP; офисный обмен остаётся в WireGuard." }, [packet("Обычный пакет после NAT", [{ name: "IPv4", value: HOME + " → " + WEB, detail: "Нет внешней оболочки WireGuard." }, { name: "Приложение", value: "HTTPS сайта — отдельная защита", detail: "Наличие или отсутствие VPN не отменяет проверку TLS." }], "Весь обмен со страницей схематично показан одним этапом; TCP, TLS и ответ сайта здесь не разыгрываются.")]);
  split.finish();

  var full = makeScenario("full");
  setup(full, true); officeTransfer(full);
  full.add("public-full-route", "result", "Публичный сайт тоже направляем в wg0", "В этом опыте полный туннель настроен для выбранного IPv4-трафика.", ["Адрес 203.0.113.80 теперь тоже попадает в выбранный маршрут через wg0. AllowedIPs офисного peer на клиенте — 0.0.0.0/0, то есть все IPv4-адреса назначения, переданные этому интерфейсу.", "Но внешний пакет WireGuard к 203.0.113.5 должен по-прежнему уходить через физическую сеть. Иначе получилась бы попытка переносить оболочку туннеля через этот же туннель. В Linux такую задачу решают отдельными маршрутами или policy routing; здесь нужный внешний путь уже настроен."], "Внутренний пакет для публичного сайта подготовлен с источником 10.7.0.2.", "Полный IPv4-туннель не означает автоматически настроенные IPv6 и DNS.", null, null, "local", "Публичный IP в wg0", innerFields(WEB, false), ["wg-quick", "wg-routing", "linux-route"], {}, [innerPacket(WEB, false)]);
  full.add("public-full-tunnel", "transfer", "Переносим запрос сайта к VPN-шлюзу", "Внешнее назначение остаётся тем же, хотя внутри другой сайт.", ["Внутри зашифрован пакет 10.7.0.2 → 203.0.113.80. Снаружи снова 198.51.100.10 → 203.0.113.5 и UDP 40000 → 51820.", "Для домашнего наблюдателя оба направления — офис и публичный сайт — выглядят как обмен с VPN-шлюзом. Это не полная невидимость: остаются внешние адреса, объём, время и возможность иных косвенных наблюдений."], "Шлюз получил защищённый пакет для публичного сайта.", "Внутренний адрес сайта здесь скрыт внутри WireGuard, внешняя точка VPN видна.", "client", "vpn", "vpn", "Сайт внутри VPN", outerFields("Зашифрованный IP-пакет", false), ["wg-routing"], { observer: "Доставка к VPN-шлюзу; внутренний адрес публичного сайта не открыт на этом участке." }, [outerPacket("Зашифрованный IP-пакет", false)]);
  full.add("egress-snat", "transfer", "Шлюз открывает пакет и меняет источник для выхода", "SNAT настроен отдельно от WireGuard.", ["После проверки и расшифрования шлюз видит назначение публичного сайта. Адрес источника 10.7.0.2 частный; в выбранной сети интернет-ответ не маршрутизируется прямо к нему.", "На шлюзе отдельно включён SNAT (замена адреса источника). Для этого опыта он меняет 10.7.0.2 на 203.0.113.5 и хранит сопоставление для обратного ответа. Нужны также пересылка и правила доступа. Простое создание WireGuard-интерфейса всего этого не обеспечивает."], "Наружу подготовлен пакет с публичным источником VPN-шлюза.", "VPN-шлюз видит внутренние IP-адреса. За ним WireGuard уже не защищает этот пакет.", null, null, "local", "SNAT на шлюзе", [field("До / после SNAT", "Выход VPN-шлюза", [["До", INNER + " → " + WEB, "Пакет после расшифрования."], ["После", GATE + " → " + WEB, "Выбранное преобразование источника для выхода в интернет."], ["Состояние NAT", "Обратное сопоставление сохранено", "Ответ можно будет направить внутреннему клиенту."]])], ["snat", "linux-route"], {}, [{ type: "table", title: "Два независимых NAT", columns: ["Где", "Что преобразует"], rows: [["Дома", "Внешнюю UDP-доставку WireGuard"], ["На VPN-шлюзе", "Внутренний пакет после расшифрования перед выходом к сайту"]], note: "Шифрование туннеля и замена адреса — разные операции." }]);
  full.add("public-egress", "transfer", "Публичный сайт получает запрос от шлюза", "Сайт видит адрес выхода VPN, а не домашний адрес.", ["К сайту приходит пакет 203.0.113.5 → 203.0.113.80 без оболочки WireGuard. Публичный сайт видит в качестве сетевого источника офисный VPN-шлюз.", "Если приложение использует HTTPS, содержимое защищено отдельно на всём пути клиента к сайту. Смена видимого IP-адреса сама по себе не скрывает пользователя от сайта: остаются его учётная запись, cookie и другие признаки."], "Пакет доставлен публичному сайту через выход VPN-шлюза.", "На участке шлюз → сайт виден адрес сайта; наличие TLS определяет защиту приложения.", "vpn", "public", "ip", "Выход в интернет", [field("IPv4", "После офисного SNAT", [["Источник → назначение", GATE + " → " + WEB, "Это уже не внешняя UDP-оболочка WireGuard."]])], ["snat"], {}, [packet("После выхода из VPN", [{ name: "IPv4", value: GATE + " → " + WEB, detail: "Источник изменён явно настроенным SNAT." }, { name: "WireGuard", value: "Оболочки нет", detail: "Туннель заканчивается на шлюзе; HTTPS не следует заменять доверием к VPN." }], "TCP-порты и содержимое TLS в этом отдельном опыте не детализируются.")]);
  full.add("public-return-snat", "transfer", "Ответ сайта возвращаем внутреннему клиенту", "Обратный NAT восстанавливает назначение 10.7.0.2.", ["Сайт отвечает на 203.0.113.5. Шлюз находит сопоставление созданного обмена и заменяет назначение ответа на 10.7.0.2. Источник остаётся 203.0.113.80.", "Полученный внутренний пакет предназначен клиентскому peer WireGuard. Он снова будет зашифрован, прежде чем уйдёт через интернет домой."], "На шлюзе готов ответ 203.0.113.80 → 10.7.0.2.", "Обратное преобразование использует запись NAT, а не угадывает пользователя по одному IP-адресу.", "public", "vpn", "ip", "Ответ + обратный NAT", [field("Обратный SNAT", "Ответ сайта на шлюзе", [["До", WEB + " → " + GATE, "Внешний ответ сайта."], ["После", WEB + " → " + INNER, "Восстановленное назначение внутреннего пакета."]])], ["snat", "wg-routing"], {}, [innerPacket(WEB, true)]);
  full.add("public-return-tunnel", "result", "Ответ сайта доходит через тот же туннель", "Путь проверен в обе стороны, но область защиты ограничена.", ["Шлюз отправляет зашифрованный ответ к 198.51.100.10:40000. Домашний NAT доставляет его ноутбуку; тот проверяет и открывает внутренний ответ сайта.", "Итог опыта: офис и выбранный публичный IPv4-трафик идут через VPN. Это ещё не проверка всей машины: отдельно нужны DNS, IPv6, исключения маршрутизации и поведение при падении туннеля. VPN также не выдаёт пользователю права на сервер и не заменяет HTTPS."], "Публичный сайт доступен через явно настроенный выход VPN.", "Снаружи дома виден ответ VPN; публичный сайт видел выход 203.0.113.5.", "vpn", "client", "vpn", "Ответ сайта в VPN", outerFields("Зашифрованный IP-пакет", true), ["wg-routing", "wg-quick", "nat"], { result: "Оба IPv4-пути через VPN", observer: "На домашнем участке — оболочка VPN; на участке шлюз → сайт — адрес публичного сайта." }, [outerPacket("Зашифрованный IP-пакет", true), innerPacket(WEB, true)]);
  full.finish();

  var missing = makeScenario("missing-route");
  missing.add("failure-task", "task", "Офисная страница не открывается", "WireGuard настроен, но этого недостаточно для доставки.", ["Из дома снова нужна рабочая страница 172.19.115.180. У ноутбука и офисного шлюза настроены правильные ключи и допустимые внутренние адреса. Но приложение не получает страницу.", "В этом опыте неисправность одна: забыли системный маршрут офисной сети через wg0. Посмотрим, почему проверка только ключей не находит такую ошибку."], "Условие неисправности задано; запрос ещё не ушёл.", "Сообщение об ошибке приложения само по себе не указывает на причину.", null, null, "local", "Нет страницы", localFields("Сбой опыта", "Нет маршрута офиса через wg0", "Ключи и остальные условия здесь исправны."), ["linux-route", "wg-quick"], {}, [note("Как будем искать", "Проверим адрес назначения, системный маршрут и только затем настройки VPN. Не будем менять все настройки сразу.")]);
  missing.add("keys-correct", "route", "Проверяем настройку ключей", "Известный peer ещё не означает, что пакет попадает к нему.", ["У клиента есть ключ офисного peer и AllowedIPs 172.19.0.0/16. На шлюзе клиенту разрешён внутренний источник 10.7.0.2/32.", "Это правильные настройки WireGuard для выбранной задачи. Но WireGuard обработает пакет только после того, как операционная система передаст пакет в его интерфейс."], "Ошибка ключей исключена условиями опыта.", "Проверка конфигурации не является передачей офисного пакета.", null, null, "local", "Peer настроен", localFields("AllowedIPs на клиенте", "172.19.0.0/16", "Выбор peer сработал бы для пакета, уже поступившего в wg0."), ["wg-routing"], {}, []);
  missing.add("route-lookup", "route", "Спрашиваем систему о пути к офисному адресу", "Выбран домашний выход, а не wg0.", ["В выбранной простой таблице есть только обычный маршрут по умолчанию через домашний маршрутизатор. Отдельного маршрута 172.19.0.0/16 → wg0 нет.", "Поэтому система выбирает физический интерфейс. AllowedIPs в WireGuard не перехватывает этот пакет сама по себе. wg-quick обычно создаёт нужный маршрут, но в данном опыте интерфейс настраивали без такого шага."], "Найден неверный выход для офисного пакета.", "Пока это локальная проверка: пакета в туннеле нет.", null, null, "local", "Не тот интерфейс", [field("Маршрут", "Результат выбранного поиска", [["Назначение", OFFICE, "Куда нужно приложение."], ["Выход", "Физическая сеть", "Выбран домашний маршрут по умолчанию."], ["Нужный маршрут", "172.19.0.0/16 → wg0 отсутствует", "Это причина данного сбоя."]])], ["linux-route", "wg-quick"], {}, [{ type: "table", title: "Настройки разошлись", columns: ["Настройка", "Есть?"], rows: [["Peer и ключи", "Да"], ["AllowedIPs офиса", "Да"], ["Системный маршрут офиса в wg0", "Нет"]], note: "В более сложной системе проверяют также выбранные таблицы и правила policy routing, а не только одну строку." }]);
  missing.add("physical-packet", "transfer", "Приложение отправляет пакет по неверному пути", "Это обычный IP-пакет, без защиты WireGuard.", ["Для выбранного физического выхода система использует локальный адрес 192.0.2.10. Пакет направляется домашнему маршрутизатору с назначением 172.19.115.180.", "Не появляется ни внешний пакет к 203.0.113.5, ни data message WireGuard. Верные ключи не могут зашифровать пакет, который вообще не поступил в wg0."], "Офисный пакет оказался у домашнего маршрутизатора, не у VPN-шлюза.", "На этом домашнем участке виден адрес назначения офиса; оболочки VPN нет.", "client", "home", "ip", "Не через VPN", [field("IPv4", "На неверном выходе", [["Источник → назначение", LAN + " → " + OFFICE, "Источник выбран для физического интерфейса."], ["WireGuard", "Не использован", "Пакет не вошёл в wg0."]])], ["linux-route", "wg-routing"], { observer: "Обычный IP к 172.19.115.180; нет зашифрованной оболочки WireGuard." }, [packet("Пакет на физическом выходе", [{ name: "IPv4", value: LAN + " → " + OFFICE, detail: "Отправлен не в виртуальный интерфейс." }, { name: "WireGuard", value: "Нет", detail: "Существование ключей не меняет выбранный системный путь.", tone: "warn" }], "Этот пример демонстрирует также риск: ошибочная маршрутизация может отправить пакет без ожидаемой VPN-защиты.")]);
  missing.add("home-drop", "transfer", "Домашний маршрутизатор не знает офисный путь", "В этой модели он отклоняет такой пакет.", ["В условиях опыта домашний маршрутизатор не пересылает назначения частной офисной сети в интернет и не имеет отдельного маршрута в офис. Пакет здесь прекращает движение.", "Это выбранная политика домашнего устройства, а не гарантия поведения любого провайдера. Даже если другое устройство отправит такой пакет дальше, частный адрес не указывает на единственный офис во всём интернете."], "Пакет отброшен дома; офисный шлюз его не видел.", "Нет доставки в туннель и нет ответа офиса.", null, null, "local", "Доставка остановлена", localFields("Место остановки", "Домашний маршрутизатор", "В выбранной модели нет пути к офисной сети."), ["linux-route", "addresses"], { result: "Офис не достигнут" }, [note("Частные адреса повторяются", "172.19.115.180 может существовать в разных организациях. Нужный офис определяется маршрутом и подключённой сетью, а не уникальностью этого числа в мире.")]);
  missing.add("no-handshake-proof", "protect", "Не называем это ошибкой шифрования", "Офисные данные до WireGuard не дошли.", ["Сбой возник до обработки данных WireGuard. Из того, что приложение не получило страницу, нельзя сделать вывод «ключи неправильные».", "Рукопожатие к публичному endpoint может отдельно работать по физической сети, пока офисный маршрут отсутствует. И наоборот, правильный маршрут не доказывает доступность endpoint. В этом опыте не запускаем дополнительный обмен: различаем причины по уже известному пути пакета."], "Граница проблемы найдена: выбор интерфейса, не расшифрование.", "В сценарии пока не отправлено ни одного VPN data message.", null, null, "local", "Разные проверки", localFields("Ключи / маршрут", "Независимые условия", "Проверять их нужно отдельно."), ["wg-routing", "wg-protocol", "linux-route"], {}, [note("Что доказано", "Неисправен заданный маршрут. Не доказаны проблемы криптографии, офисного сервера или пользовательских прав: пакет до них не дошёл.")]);
  missing.add("diagnostic-order", "result", "Составляем короткую цепочку проверки", "Ищем первое место, где фактический путь расходится с ожидаемым.", ["Сначала проверяем: приложение обращается к нужному адресу? Какой интерфейс выбрал маршрут? Затем: есть ли peer для этого адреса в AllowedIPs, достижим ли внешний endpoint, проходит ли служебный обмен?", "После этого проверяют правила пересылки и обратный путь в офисе, а затем само приложение. Такой порядок не универсальная команда ремонта, но не даёт принять один зелёный индикатор VPN за проверку всего соединения."], "Есть план проверки по участкам, а не случайная замена настроек.", "Каждая проверка отвечает на свой вопрос.", null, null, "local", "Проверки по пути", localFields("Первое расхождение", "Выбран физический интерфейс", "Именно его нужно исправить в этом опыте."), ["linux-route", "wg-routing"], {}, [{ type: "table", title: "Что проверяет каждый уровень", columns: ["Проверка", "Не доказывает"], rows: [["Маршрут выбирает wg0", "Что endpoint доступен"], ["Handshake успешен", "Что есть офисный обратный маршрут"], ["Сервер получил IP-пакет", "Что пользователь имеет право читать страницу"]], note: "Не добавляем новые неисправности: здесь неверен только системный маршрут." }]);
  missing.add("repair-route", "route", "Добавляем недостающий маршрут в модели", "Теперь будущие офисные пакеты должны попадать в wg0.", ["Для выбранного опыта исправление — направить 172.19.0.0/16 в интерфейс wg0. AllowedIPs и ключи не меняем: они уже соответствовали задаче.", "Одновременно оставляем внешний путь к 203.0.113.5 через физическую сеть. Нажатие в этой лаборатории меняет только учебное состояние, а не таблицу маршрутов вашего компьютера."], "Системный маршрут исправлен; старый отброшенный пакет не оживает.", "Новых офисных данных в этом шаге не отправлено.", null, null, "local", "Маршрут исправлен", localFields("Маршрут офиса", "172.19.0.0/16 → wg0", "Применяется к следующей попытке передачи."), ["linux-route", "wg-quick"], { route: "Офис через wg0" }, [note("Изменение — не проверка результата", "Новая настройка создаёт предпосылку доставки. Её нужно проверить новой попыткой, а не считать старый запрос автоматически успешным.")]);
  missing.add("verify-next", "result", "Проверяем будущий путь отдельно от результата страницы", "Восстановленный маршрут — необходимый шаг, не доказательство всей цепочки.", ["Повторный локальный выбор пути теперь указывает на wg0. Это проверяет именно исправленную настройку.", "Чтобы пройти остальные участки доставки, выберите «Только офис через VPN»: там показаны рукопожатие, вложение IP в UDP, пересылка и обратный ответ. Здесь останавливаемся до новой передачи: так видно, что именно было исправлено."], "Маршрут исправлен и проверен; успешная страница ещё не изображалась.", "В этом сценарии нет доставленных VPN-данных: ни до исправления, ни после него.", null, null, "local", "Готово к новой попытке", localFields("Повторный выбор пути", "wg0", "Это проверка маршрута, не измерение ответа приложения."), ["linux-route"], { result: "Маршрут исправлен; обмен не повторён" }, [note("Главный вывод", "AllowedIPs выбирает peer внутри WireGuard. Системный маршрут сначала должен привести пакет в WireGuard. Одно не следует автоматически из другого, если настройку выполняет не согласующая их утилита.")]);
  missing.add("failure-summary", "result", "Отделяем исправление от обещания успеха", "Нашли конкретную причину, а не проверили сеть целиком.", ["В исходном состоянии офисный пакет уходил к домашнему маршрутизатору без WireGuard. Исправили именно выбор интерфейса: теперь следующий пакет должен поступить в wg0.", "Если новая попытка всё ещё не даст страницу, проверку продолжают дальше по цепочке. Не нужно снова менять исправный маршрут только потому, что причина следующего сбоя может быть на другом участке."], "Область результата ограничена исправленным маршрутом.", "Эта модель не обращалась к реальному офисному серверу.", null, null, "local", "Причина и предел проверки", localFields("Доказанный результат", "Будущий офисный путь ведёт в wg0", "Успешный прикладной обмен в этом сценарии не воспроизводился."), ["linux-route", "wg-routing"], {}, [note("Короткий ответ для собеседования", "Маршрут приводит пакет в интерфейс WireGuard. AllowedIPs выбирает peer внутри этого интерфейса. Ключи защищают обмен с peer, но не создают недостающий системный маршрут сами по себе.")]);
  missing.finish();

  var expired = makeScenario("expired-nat");
  expired.add("idle-task", "task", "Раньше уведомления приходили, после простоя — нет", "Ноутбук дома должен получить сообщение от офисного сервиса.", ["Представим офисный сервис, который присылает обновление уже подключённому ноутбуку. Пока ноутбук сам обменивался данными, обновления приходили. После паузы следующее сообщение до него не дошло.", "Маршруты, ключи и права в этом опыте не менялись. Посмотрим на другое условие доставки: помнит ли домашний маршрутизатор, как передать входящий UDP-пакет этому ноутбуку."], "Задан ранее работавший обмен; отслеживаем только домашний NAT.", "Считаем ключи передачи пригодными в течение выбранного опыта.", null, null, "local", "Было подключение", localFields("Условие опыта", "Маршруты и ключи исправны", "Изолируем исчезновение UDP-сопоставления."), ["wg-keepalive", "nat"], { handshake: "Готовы", nat: "40000 → 51821", result: "Ожидаем обновление" }, [note("Откуда взялась запись", "До начала опыта ноутбук отправлял WireGuard с 192.0.2.10:51821 к 203.0.113.5:51820. Домашний NAT создал внешнее сопоставление 198.51.100.10:40000.")]);
  expired.add("mapping-alive", "route", "Входящий ответ пока имеет известный путь", "У NAT есть временная запись выбранного UDP-обмена.", ["Пакет к 198.51.100.10:40000 от настроенного внешнего endpoint может быть передан к 192.0.2.10:51821 по имеющейся записи и правилам выбранного маршрутизатора.", "Это состояние NAT, а не пользовательский вход в офис и не криптографическая сессия WireGuard. У этих механизмов разные состояния и причины отказа."], "Запись NAT действительна; путь входящего UDP известен.", "В модели время не отсчитывается; состояние задаётся шагами.", null, null, "local", "Запись есть", localFields("Сопоставление NAT", HOME + ":40000 → " + LAN + ":51821", "Для обмена с выбранным endpoint 203.0.113.5:51820."), ["nat", "wg-keepalive"], {}, [{ type: "table", title: "Три независимых условия", columns: ["Механизм", "Что хранит"], rows: [["NAT", "Куда передать внешний UDP-ответ"], ["WireGuard", "Peer и пригодные ключи передачи"], ["Приложение", "Кому разрешено читать данные"]], note: "Удаление первой записи само по себе не меняет вторую и третью." }]);
  expired.add("mapping-expires", "route", "После выбранного простоя NAT удаляет запись", "Для этого опыта входящий путь больше не известен.", ["Домашний маршрутизатор удаляет сопоставление. Конкретная пауза зависит от устройства и настроек; здесь нет секундомера и утверждения «у всех NAT один тайм-аут».", "WireGuard старается не передавать лишнее при отсутствии работы. Опция PersistentKeepalive позволяет клиенту периодически посылать защищённые пустые сообщения, чтобы поддерживать нужное состояние NAT или firewall. В начале этого сценария она выключена."], "Старая запись 40000 → 51821 исчезла.", "Ключи и маршруты не изменились; изменилось только состояние домашнего NAT.", null, null, "local", "Запись удалена", localFields("Домашний NAT", "Запись удалена", "Условное событие модели, не универсальная длительность простоя."), ["nat", "wg-keepalive"], { nat: "Запись удалена" }, [note("Не путать с обновлением ключей", "В реальном WireGuard есть собственные таймеры и обновление ключей. Здесь выбрана пауза, после которой данные ещё можно защищать имеющимися ключами; проверяем только NAT.")]);
  expired.add("incoming-to-old", "transfer", "Шлюз отправляет сообщение по старому адресу клиента", "Внешний endpoint ещё записан как 198.51.100.10:40000.", ["Офисный шлюз помнит внешний адрес и порт, с которых приходили аутентифицированные сообщения ноутбука. Он посылает защищённый пакет туда же.", "Шлюз не может прочитать внутреннюю таблицу домашнего маршрутизатора и заранее узнать, что запись исчезла. Корректное шифрование не создаёт у другого устройства недостающую запись NAT."], "Защищённый пакет дошёл до домашнего внешнего адреса, но не до ноутбука.", "Снаружи видна обратная UDP-доставка к старому порту.", "vpn", "home", "vpn", "На старый порт", outerFields("Зашифрованный IP-пакет", true), ["wg-routing", "nat"], { observer: "Входящий UDP 51820 → 40000; защищённое содержимое не раскрыто." }, [outerPacket("Зашифрованный IP-пакет", true)], true);
  expired.add("incoming-dropped", "transfer", "Домашний NAT не передаёт пакет ноутбуку", "Без записи и отдельного правила вход не разрешён в этой модели.", ["Для порта 40000 больше нет сопоставления и не задано отдельное правило проброса порта. Выбранный маршрутизатор отбрасывает входящий UDP-пакет.", "Ноутбук ничего не расшифровывает: сообщение не дошло до него. Из этого нельзя заключить, что WireGuard отверг ключ или офисный сервис отозвал права пользователя."], "Входящее обновление потеряно до проверки WireGuard на ноутбуке.", "Сбой доставки, не обнаруженная ошибка аутентификации.", null, null, "local", "До ноутбука не дошло", localFields("Граница отказа", "Домашний NAT", "Ключи клиента в этом шаге не проверялись."), ["nat", "wg-keepalive"], { result: "Обновление не доставлено" }, [note("Почему сервер не исправит это повтором сам", "Повтор на тот же забытый внешний порт в выбранной сети снова встретит тот же запрет. Нужен исходящий обмен клиента либо отдельно настроенная входящая достижимость.")]);
  expired.add("keepalive-choice", "protect", "Планируем исходящий keepalive", "Он поддерживает путь доставки, а не выдаёт новые права.", ["Keepalive — короткое служебное сообщение для поддержания обмена. В WireGuard это аутентифицированное защищённое сообщение с пустыми внутренними данными; оно не несёт офисную страницу.", "Для клиента, которому нужен входящий трафик после простоя, можно настроить PersistentKeepalive с подходящим интервалом. Если ключи уже устарели, WireGuard сначала организует нужное обновление; здесь ключи ещё пригодны."], "Выбрано отправить пустое защищённое сообщение изнутри домашней сети.", "Настройка keepalive не заменяет пароль, ключ peer или правила офисного доступа.", null, null, "local", "Поддержать доставку", localFields("Содержимое keepalive", "Пустые внутренние данные", "Не TCP-запрос, не новая пользовательская авторизация."), ["wg-protocol", "wg-keepalive"], {}, [note("Не включать механически везде", "PersistentKeepalive нужен не каждому peer. Его применяют, когда необходимо поддерживать подходящее состояние NAT/firewall для ожидаемого входящего обмена.")]);
  expired.add("keepalive-out", "transfer", "Ноутбук отправляет сообщение к доступному шлюзу", "Исходящая передача заново создаёт выбранное сопоставление NAT.", ["Ноутбук отправляет UDP с 192.0.2.10:51821 к 203.0.113.5:51820 по известному физическому пути. Маршрутизатор разрешает такой исходящий обмен и создаёт новое сопоставление.", "Для наглядности внешний порт теперь 40001, а не 40000. Это условие опыта: NAT может сохранить старый порт или выбрать другой. Главное — запись снова есть, и сообщение дошло до доступного VPN-шлюза."], "Создано новое сопоставление 40001 → 51821; шлюз получил keepalive.", "Видны внешние адреса и новый UDP-порт, но нет полезной нагрузки приложения.", "client", "vpn", "vpn", "Пустой keepalive", outerFields("Пустое защищённое сообщение", false, "40001"), ["wg-keepalive", "nat", "wg-protocol"], { nat: "40001 → 51821", observer: "Исходящий UDP 40001 → 51820 с пустым защищённым сообщением WireGuard." }, [outerPacket("Пустое защищённое сообщение", false, "40001")]);
